// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Apply security headers
app.use(helmet());

// Apply rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests, please try again later.'
  }
});
app.use(limiter);

// Body parser middleware for JSON payloads
app.use(express.json({ limit: '10mb' }));

// Input validation helper function
const validateId = (id) => {
  if (!id || isNaN(id) || parseInt(id) <= 0) {
    return false;
  }
  return true;
};

// Input sanitization helper function
const sanitizeString = (str) => {
  if (typeof str !== 'string') return '';
  return str.trim().replace(/[^a-zA-Z0-9\s\-_@.]/g, '');
};

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? 'Something went wrong!' : err.message
  });
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with proper error handling
app.get('/users', (req, res, next) => {
  try {
    // In a real application, this would fetch from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (error) {
    next(error);
  }
});

// Get specific user by ID with input validation
app.get('/users/:id', (req, res, next) => {
  try {
    const userId = req.params.id;

    // Validate input
    if (!validateId(userId)) {
      return res.status(400).json({
        error: 'Invalid user ID',
        message: 'User ID must be a positive integer'
      });
    }

    // Convert to integer
    const id = parseInt(userId);

    // In a real application, this would query a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        message: `User with ID ${id} does not exist`
      });
    }

    // Sanitize output before sending
    const sanitizedUser = {
      id: user.id,
      name: sanitizeString(user.name),
      email: sanitizeString(user.email)
    };

    res.json(sanitizedUser);
  } catch (error) {
    next(error);
  }
});

// Create user endpoint with validation
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Validate inputs
    if (!name || typeof name !== 'string' || name.trim().length === 0) {
      return res.status(400).json({
        error: 'Invalid name',
        message: 'Name is required and must be a non-empty string'
      });
    }

    if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      return res.status(400).json({
        error: 'Invalid email',
        message: 'Valid email is required'
      });
    }

    // Sanitize inputs
    const sanitizedName = sanitizeString(name);
    const sanitizedEmail = sanitizeString(email);

    // In a real application, this would save to a database
    const newUser = {
      id: Math.floor(Math.random() * 1000) + 3, // Avoid conflicts with existing IDs
      name: sanitizedName,
      email: sanitizedEmail
    };

    res.status(201).json(newUser);
  } catch (error) {
    next(error);
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: 'The requested resource does not exist'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? 'An unexpected error occurred' : err.message
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

