#!/usr/bin/env node

// Script to verify the validity of credentials in .env.test
require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const https = require('https');

async function testDatabaseConnection() {
  console.log('Testing DATABASE_URL...');

  if (!process.env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found in environment');
    return false;
  }

  const client = new Client({
    connectionString: process.env.DATABASE_URL
  });

  try {
    await client.connect();
    console.log('✅ Database connection successful');
    await client.end();
    return true;
  } catch (error) {
    console.log(`❌ Database connection failed: ${error.message}`);
    return false;
  }
}

function testHTTPAPI(url, headers = {}) {
  return new Promise((resolve) => {
    const options = {
      method: 'GET',
      headers: headers
    };

    const req = https.request(url, options, (res) => {
      resolve(res.statusCode < 400); // Consider 2xx and 3xx as successful
    });

    req.on('error', (error) => {
      console.log(`Request error: ${error.message}`);
      resolve(false);
    });

    req.setTimeout(5000, () => {
      req.destroy();
      resolve(false);
    });

    req.end();
  });
}

async function testAnthropicAPI() {
  console.log('Testing ANTHROPIC_API_KEY...');

  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found in environment');
    return false;
  }

  // Test with a simple models list request
  const isValid = await testHTTPAPI('https://api.anthropic.com/v1/models', {
    'x-api-key': process.env.ANTHROPIC_API_KEY,
    'anthropic-version': '2023-06-01'
  });

  console.log(isValid ? '✅ Anthropic API key appears valid' : '❌ Anthropic API key invalid or request failed');
  return isValid;
}

async function testStripeAPI() {
  console.log('Testing STRIPE_SECRET_KEY...');

  if (!process.env.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not found in environment');
    return false;
  }

  // Test with a simple request to list balance (requires authentication)
  const isValid = await testHTTPAPI('https://api.stripe.com/v1/balance', {
    'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}`
  });

  console.log(isValid ? '✅ Stripe API key appears valid' : '❌ Stripe API key invalid or request failed');
  return isValid;
}

async function testAWSCredentials() {
  console.log('Testing AWS credentials...');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found in environment');
    return false;
  }

  // For AWS, we'll just verify the keys are present and have the expected format
