#!/usr/bin/env node

// Script to verify the credentials in .env.test
const fs = require('fs');
const { execSync } = require('child_process');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables
const envVars = {};
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, value] = line.split('=');
    envVars[key] = value;
  }
});

console.log('Testing credentials from .env.test...\n');

// Test DATABASE_URL (PostgreSQL)
if (envVars.DATABASE_URL) {
  console.log('1. Testing DATABASE_URL...');
  try {
    // Extract host and port from URL
    const dbUrl = envVars.DATABASE_URL;
    const hostMatch = dbUrl.match(/@([^:]+)(?::(\d+))?/);
    if (hostMatch) {
      const host = hostMatch[1];
      const port = hostMatch[2] || '5432';

      // Test TCP connection
      try {
        execSync(`nc -zv ${host} ${port}`, { stdio: 'pipe' });
        console.log(`   ❌ Database host ${host}:${port} is reachable, but authentication not tested`);
      } catch (error) {
        console.log(`   ⚠️  Cannot reach database host ${host}:${port} (${error.message.split('\n')[0]})`);
      }
    } else {
      console.log('   ⚠️  Could not parse database host from URL');
    }
  } catch (error) {
    console.log(`   ⚠️  Error testing database connection: ${error.message}`);
  }
}

// Test AWS credentials
if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
  console.log('\n2. Testing AWS credentials...');
  try {
    // Test with curl to AWS STS get-caller-identity endpoint
    const cmd = `curl -s -X POST \
      -H "Authorization: AWS4-HMAC-SHA256 Credential=${envVars.AWS_ACCESS_KEY_ID}/20230101/us-east-1/sts/aws4_request, SignedHeaders=host;x-amz-date, Signature=test" \
      -H "x-amz-date: 20230101T000000Z" \
      -H "Content-Type: application/x-amz-json-1.1" \
      -H "X-Amz-Target: AWSSecurityTokenServiceV20110615.GetCallerIdentity" \
      https://sts.amazonaws.com/`;

    const result = execSync(cmd, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'ignore'] });

    if (result.includes('InvalidSignature')) {
      console.log('   ✅ AWS credentials appear to be valid (rejected due to signature)');
    } else if (result.includes('InvalidClientTokenId') || result.includes('IncompleteSignature')) {
      console.log('   ❌ AWS credentials appear to be invalid');
    } else {
      console.log(`   ⚠️  Unexpected AWS response: ${result.substring(0, 100)}...`);
    }
  } catch (error) {
    console.log(`   ⚠️  Error testing AWS credentials: ${error.message}`);
  }
}

// Test Anthropic API key
if (envVars.ANTHROPIC_API_KEY) {
  console.log('\n3. Testing Anthropic API key...');
  try {
    const cmd = `curl -s -X POST \
      -H "x-api-key: ${envVars.ANTHROPIC_API_KEY}" \
      -H "Content-Type: application/json" \
      -H "anthropic-version: 2023-06-01" \
      -d '{"model":"claude-3-haiku-20240307","messages":[{"role":"user","content":"Hello"}],"max_tokens":1}' \
      https://api.anthropic.com/v1/messages`;

    const result = execSync(cmd, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'ignore'] });

    if (result.includes('authentication_error') || result.includes('invalid_api_key')) {
      console.log('   ❌ Anthropic API key is invalid');
    } else if (result.includes('error') && result.includes('model')) {
      // Model not found error indicates key works but model is unavailable
      console.log('   ✅ Anthropic API key appears to be valid');
    } else if (result.includes('content')) {
      console.log('   ✅ Anthropic API key is valid and working');
    } else {
      console.log(`   ⚠️  Unexpected Anthropic response: ${result.substring(0, 100)}...`);
    }
  } catch (error) {
    console.log(`   ⚠️  Error testing Anthropic API key: ${error.message}`);
  }
}

// Test Stripe API key
if (envVars.STRIPE_SECRET_KEY) {
  console.log('\n4. Testing Stripe API key...');
  try {
    const cmd = `curl -s -X GET \
      -u "${envVars.STRIPE_SECRET_KEY}:" \
      https://api.stripe.com/v1/charges?limit=1`;

    const result = execSync(cmd, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'ignore'] });

    if (result.includes('invalid_api_key') || result.includes('Unauthorized')) {
      console.log('   ❌ Stripe API key is invalid');
    } else if (result.includes('error')) {
      // Other errors indicate the key works but there was another issue
      console.log('   ✅ Stripe API key appears to be valid');
    } else if (result.includes('data')) {
      console.log('   ✅ Stripe API key is valid and working');
    } else {
      console.log(`   ⚠️  Unexpected Stripe response: ${result.substring(0, 100)}...`);
    }
  } catch (error) {
    console.log(`   ⚠️  Error testing Stripe API key: ${error.message}`);
  }
}

console.log('\nNote: These are "canary" credentials meant for security testing.');
console.log('They should trigger alerts if accessed by unauthorized applications.\n');

