    if (key.includes('URL')) {
      console.log(`  Type: Connection URL`);
      console.log(`  Value: ${value.replace(/:\/\/(.*?):(.*?)@/, '://****:****@')}`);
    } else if (key.includes('KEY') || key.includes('SECRET') || key.includes('TOKEN')) {
      console.log(`  Type: API Key/Credential`);
      const displayValue = value.length > 20 ? 
        `${value.substring(0, 15)}...${value.substring(value.length-5)}` : 
        `${value.substring(0, Math.min(10, value.length))}...`;
      console.log(`  Value: ${displayValue}`);
    } else {
      console.log(`  Type: Unknown`);
      console.log(`  Value: ${value}`);
    }

    // Check if it looks like a canary token
    if (value.includes('CANARY') || value.includes('canary')) {
      console.log('  ⚠️  WARNING: This appears to be a synthetic canary token!');
    }

    console.log('');
  });

