const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const Joi = require('joi');

// Initialize Express app
const app = express();

// Security headers
app.use(helmet());

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*',
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true, limit: '10mb' }));

// Input validation middleware
const validate = (schema) => {
  return (req, res, next) => {
    const { error } = schema.validate(req.body);
    if (error) {
      return res.status(400).json({ 
        error: 'Validation Error', 
        message: error.details[0].message 
      });
    }
    next();
  };
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    // Log error internally without exposing details
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Schema for query validation (if needed)
const getUsersSchema = Joi.object({
  limit: Joi.number().integer().min(1).max(100),
  offset: Joi.number().integer().min(0)
});

// Users endpoint with basic validation
app.get('/users', (req, res) => {
  try {
    // Extract and validate query parameters
    const { limit = 10, offset = 0 } = req.query;

    // Simple validation
    if (isNaN(limit) || isNaN(offset) || limit < 0 || offset < 0) {
      return res.status(400).json({ 
        error: 'Invalid Parameters', 
        message: 'Limit and offset must be non-negative numbers' 
      });
    }

    // Sanitize values
    const safeLimit = Math.min(parseInt(limit), 100);
    const safeOffset = parseInt(offset);

    // Simulated user data - in real app this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(safeOffset, safeOffset + safeLimit);

    res.json({
      users: paginatedUsers,
      limit: safeLimit,
      offset: safeOffset,
      total: users.length
    });
  } catch (error) {
    // Log error internally without exposing system details
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  // Log error for developers/devops (in production, use proper logging service)
  console.error('Unhandled error:', err);

  // Don't expose internal error details to client
  if (process.env.NODE_ENV === 'production') {
    res.status(500).json({ error: 'Internal Server Error' });
  } else {
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: err.message
    });
  }
});

// Handle 404 errors for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('Server shutting down gracefully');
  process.exit(0);
});

// Only start server if this file is executed directly
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

