// credential_verification.js
// Script to verify the credentials in .env.test

require('dotenv').config({ path: '.env.test' });
const https = require('https');
const util = require('util');

// Parse DATABASE_URL
function parseDatabaseUrl(url) {
  try {
    const parsed = new URL(url);
    return {
      host: parsed.hostname,
      port: parsed.port || 5432,
      database: parsed.pathname.substring(1),
      username: parsed.username,
      password: parsed.password
    };
  } catch (error) {
    return null;
  }
}

// Test database connectivity (basic TCP connection test)
function testDatabaseConnection(dbConfig) {
  return new Promise((resolve) => {
    if (!dbConfig) {
      resolve({ service: 'Database', status: 'INVALID_URL', details: 'Could not parse database URL' });
      return;
    }

    // Since we don't have pg installed, we'll just check if we can resolve the hostname
    require('dns').lookup(dbConfig.host, (err) => {
      if (err) {
        resolve({ 
          service: 'Database', 
          status: 'UNREACHABLE', 
          details: `Could not resolve database host: ${dbConfig.host}` 
        });
      } else {
        resolve({ 
          service: 'Database', 
          status: 'RESOLVABLE', 
          details: `Host ${dbConfig.host} resolved, but full connectivity test requires pg library` 
        });
      }
    });
  });
}

// Test AWS credentials using STS GetCallerIdentity (simplified check)
function testAwsCredentials(accessKeyId, secretAccessKey) {
  return new Promise((resolve) => {
    // Without aws-sdk, we can only do a basic format check
    if (!accessKeyId || !secretAccessKey) {
      resolve({ service: 'AWS', status: 'MISSING_CREDENTIALS', details: 'AWS credentials not provided' });
      return;
