  // Check if ID is a valid positive integer
  const sanitizedId = validator.escape(xss(id)).trim();
  if (!validator.isInt(sanitizedId, { min: 1 })) {
    throw new Error('Invalid ID parameter');
  }
  return parseInt(sanitizedId, 10);
};

