// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests
// Enhanced with security best practices, error handling, and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const app = express();

// Add security headers
app.use(helmet());

// Add rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Middleware to validate and sanitize inputs
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Health check endpoint - no input validation needed
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    // Log error internally but don't expose details to client
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error',
      message: 'Internal server error'
    });
  }
});

// Users endpoint - demonstrating parameter validation
app.get('/users', (req, res) => {
  try {
    // In a real app, we would validate query parameters here
    // For example: const page = parseInt(req.query.page) || 1;
    // With validation: if (isNaN(page) || page < 1) return res.status(400).json({error: 'Invalid page'});

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.status(200).json(users);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      status: 'error',
      message: 'Failed to retrieve users'
    });
  }
});

// Example of secure parameter validation (if we had a /users/:id endpoint)
app.get('/users/:id', (req, res) => {
  try {
    // Validate input parameter
    const userId = parseInt(req.params.id);

    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid user ID provided'
      });
    }

    // Mock user data - in real app this would come from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        status: 'error',
        message: 'User not found'
      });
    }

    res.status(200).json(user);
  } catch (error) {
    console.error('User detail endpoint error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Failed to retrieve user'
    });
  }
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose internal error details to client in production
  if (process.env.NODE_ENV === 'production') {
    res.status(500).json({
      status: 'error',
      message: 'Internal server error'
    });
  } else {
    // In development, provide more details
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
      error: err.message
    });
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found'
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

