async function testAWSKeys() {
  console.log('\nTesting AWS credentials...');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found in environment');
    return false;
  }

  // Check format of AWS keys without making actual AWS calls
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  const isValidAccessKey = accessKeyId.length === 20 && accessKeyId.startsWith('AKIA');
  const isValidSecretKey = secretAccessKey.length >= 16; // Simplified check

  if (isValidAccessKey && isValidSecretKey) {
    console.log('✅ AWS credentials have valid formats');
    console.log('   NOTE: Actual AWS service calls not made for security');
    return true;
  } else {
    console.log('❌ AWS credentials do not have valid formats');
    return false;
  }
}

async function testAnthropicAPI() {
  console.log('\nTesting ANTHROPIC_API_KEY...');

  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found in environment');
    return false;
  }

  // Make a lightweight API call to verify the key
  try {
    const response = await axios.post(
      'https://api.anthropic.com/v1/messages',
      {
        model: 'claude-3-haiku-20240307',
        messages: [{ role: 'user', content: 'Hello' }],
        max_tokens: 1
      },
      {
        headers: {
          'x-api-key': process.env.ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        },
        timeout: 10000 // 10 second timeout
      }
    );

    console.log('✅ ANTHROPIC_API_KEY is valid');
    return true;
  } catch (error) {
    if (error.response) {
      // If we get a response, the key is likely valid but we're missing parameters
      if (error.response.status === 400 || error.response.status === 401) {
        console.log('❌ ANTHROPIC_API_KEY is invalid or expired');
        return false;
      } else {
        // Other status codes mean the key is valid
        console.log('✅ ANTHROPIC_API_KEY appears valid (server responded with status ' + error.response.status + ')');
        return true;
      }
    } else {
      // Network or other errors
      console.log('⚠️  Unable to verify ANTHROPIC_API_KEY due to connection error: ' + error.message);
      return null;
    }
  }
}

