        return false;
      } else {
        // Other status codes (like 403) actually indicate the key is valid
        console.log('✅ STRIPE_SECRET_KEY appears valid (server responded with status ' + error.response.status + ')');
        return true;
      }
    } else {
      console.log('⚠️  Unable to verify STRIPE_SECRET_KEY due to connection error: ' + error.message);
      return null;
    }
  }
