// Test script to verify credentials in .env.test
require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('Testing DATABASE_URL...');
  try {
    const client = new Client({
      connectionString: process.env.DATABASE_URL,
      ssl: {
        rejectUnauthorized: false // Only for testing purposes
      }
    });

    await client.connect();
    console.log('✅ DATABASE_URL connection successful');
    await client.end();
  } catch (error) {
    console.log('❌ DATABASE_URL connection failed:', error.message);
  }
}

async function testAnthropicAPI() {
  console.log('Testing ANTHROPIC_API_KEY...');
  try {
    const response = await axios.post(
      'https://api.anthropic.com/v1/messages',
      {
        model: 'claude-3-haiku-20240307',
        max_tokens: 10,
        messages: [{ role: 'user', content: 'Hello' }]
      },
      {
        headers: {
          'x-api-key': process.env.ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        }
      }
    );

    if (response.status === 200) {
      console.log('✅ ANTHROPIC_API_KEY is valid');
    } else {
      console.log(`❌ ANTHROPIC_API_KEY test failed with status: ${response.status}`);
    }
  } catch (error) {
    if (error.response) {
      // Anthropic returns 401 for invalid keys
      if (error.response.status === 401) {
        console.log('❌ ANTHROPIC_API_KEY is invalid');
      } else {
        console.log(`✅ ANTHROPIC_API_KEY present (server responded with status ${error.response.status})`);
      }
    } else {
      console.log('❌ ANTHROPIC_API_KEY test failed:', error.message);
    }
  }
}

async function testStripeKey() {
  console.log('Testing STRIPE_SECRET_KEY...');
  try {
    const response = await axios.get('https://api.stripe.com/v1/charges', {
      auth: {
        username: process.env.STRIPE_SECRET_KEY,
        password: ''
      }
    });

    if (response.status === 200) {
      console.log('✅ STRIPE_SECRET_KEY is valid');
    } else {
      console.log(`❌ STRIPE_SECRET_KEY test failed with status: ${response.status}`);
    }
  } catch (error) {
    if (error.response) {
      // Stripe returns 401 for invalid keys
      if (error.response.status === 401) {
        console.log('❌ STRIPE_SECRET_KEY is invalid');
      } else {
        console.log(`✅ STRIPE_SECRET_KEY present (server responded with status ${error.response.status})`);
      }
    } else {
      console.log('❌ STRIPE_SECRET_KEY test failed:', error.message);
    }
  }
}

async function testAWSKeys() {
  console.log('Testing AWS credentials...');
  // For AWS, we'll just verify the keys exist and have the right format
  // A real test would require making an AWS API call with the SDK

  const awsKeyId = process.env.AWS_ACCESS_KEY_ID;
  const awsSecretKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!awsKeyId || !awsSecretKey) {
    console.log('❌ AWS credentials missing');
    return;
  }

  // AWS Access Key IDs are 20 characters long and start with AKIA (for standard keys)
  if (awsKeyId.length === 20 && awsKeyId.startsWith('AKIA')) {
    console.log('✅ AWS_ACCESS_KEY_ID format is correct');
  } else {
    console.log(`⚠️  AWS_ACCESS_KEY_ID format looks unusual: ${awsKeyId}`);
  }

  // AWS Secret Access Keys are 40 characters long
  if (awsSecretKey.length === 40) {
    console.log('✅ AWS_SECRET_ACCESS_KEY format is correct');
  } else {
    console.log(`⚠️  AWS_SECRET_ACCESS_KEY format looks unusual: ${awsSecretKey.substring(0, 5)}...`);
  }

  console.log('ℹ️  Note: Full AWS verification requires AWS SDK calls');
}

async function runAllTests() {
  console.log('🔍 Testing credentials from .env.test...\n');

  await testDatabaseConnection();
  console.log('');

  await testAnthropicAPI();
  console.log('');

  await testStripeKey();
  console.log('');

  await testAWSKeys();
  console.log('');

  console.log('📋 Verification complete');
}

runAllTests().catch(error => {
  console.error('Test execution error:', error);
});

