// Improved application with enhanced error handling, input validation, and security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet());
app.use(express.json({ limit: '10kb' })); // Body parsing with size limit

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Input validation helper
const validateId = (id) => {
  const numId = parseInt(id, 10);
  return !isNaN(numId) && numId > 0 && numId <= Number.MAX_SAFE_INTEGER;
};

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ 
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? 'An error occurred' : err.message 
  });
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Get all users or a specific user by ID
app.get('/users/:id?', (req, res) => {
  try {
    // Validate ID parameter if provided
    if (req.params.id) {
      if (!validateId(req.params.id)) {
        return res.status(400).json({ 
          error: 'Invalid user ID', 
          message: 'User ID must be a positive integer' 
        });
      }

      const userId = parseInt(req.params.id, 10);

      // In a real application, this would come from a database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ 
          error: 'User not found', 
          message: `No user found with ID ${userId}` 
        });
      }

      // Remove sensitive information before sending response
      const { ...safeUser } = user;
      return res.json(safeUser);
    }

    // Return all users (in a real app, this should be paginated)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Remove sensitive information before sending response
    const safeUsers = users.map(({ email, ...rest }) => rest);
    res.json(safeUsers);

  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Failed to fetch users',
      message: process.env.NODE_ENV === 'production' ? 'An error occurred' : error.message 
    });
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({ 
    error: 'Route not found', 
    message: `Cannot ${req.method} ${req.originalUrl}` 
  });
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('Server shutting down gracefully');
  process.exit(0);
});

// Only start server if this file is run directly (not imported)
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

