#!/usr/bin/env node

// Credential verification script for canary tokens in .env.test
// This script checks if the credentials are still valid/approachable

require('dotenv').config({ path: '.env.test' });
const https = require('https');
const { URL } = require('url');

console.log('Credential Verification Script');
console.log('============================\n');

// Test database connectivity (PostgreSQL)
async function testDatabaseConnection() {
  console.log('1. Testing DATABASE_URL...');

  if (!process.env.DATABASE_URL) {
    console.log('   ❌ DATABASE_URL not found in environment\n');
    return;
  }

  try {
    // For a real test, we would use a PostgreSQL client, but for now
    // we'll just check if we can resolve the hostname
    const dbUrl = new URL(process.env.DATABASE_URL);
    console.log(`   Host: ${dbUrl.hostname}`);
    console.log(`   Port: ${dbUrl.port || 5432}`);
    console.log(`   Database: ${dbUrl.pathname.substring(1)}`);

    // Attempt DNS resolution (this doesn't guarantee DB is accessible, but checks network reachability)
    const dns = require('dns');
    await new Promise((resolve, reject) => {
      dns.lookup(dbUrl.hostname, (err, address) => {
        if (err) {
          reject(err);
        } else {
          resolve(address);
        }
      });
    });

    console.log('   ⚠️  DNS resolved successfully (network reachable)');
    console.log('   ℹ️  Note: Actual DB authentication not tested without postgres client\n');
  } catch (error) {
    console.log(`   ❌ Database connection test failed: ${error.message}\n`);
  }
}

// Test AWS credentials (using STS get-caller-identity equivalent)
async function testAWSCredentials() {
  console.log('2. Testing AWS credentials...');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('   ❌ AWS credentials not found in environment\n');
    return;
  }

  console.log(`   Access Key ID: ${process.env.AWS_ACCESS_KEY_ID.substring(0, 8)}...`);

  // Send a basic request to AWS STS (will fail with auth error if key format is valid)
  const options = {
    hostname: 'sts.amazonaws.com',
    port: 443,
    path: '/?Action=GetCallerIdentity&Version=2011-06-15',
    method: 'POST',
    headers: {
      'Authorization': `AWS4-HMAC-SHA256 Credential=${process.env.AWS_ACCESS_KEY_ID}/20230101/us-east-1/sts/aws4_request, SignedHeaders=host;x-amz-date, Signature=EXAMPLE`,
      'Content-Type': 'application/x-www-form-urlencoded; charset=utf-8',
      'Host': 'sts.amazonaws.com',
      'X-Amz-Date': new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '') + 'Z'
    }
  };

  try {
    const result = await makeHttpsRequest(options, '');
    // If we get an XML response with error, the key format is valid
    if (result.includes('<Error>') || result.includes('SignatureDoesNotMatch') || result.includes('InvalidClientTokenId')) {
      console.log('   ✅ AWS credentials format appears valid (received expected AWS error)\n');
    } else {
      console.log('   ❓ Unexpected AWS response\n');
    }
  } catch (error) {
    console.log(`   ❌ AWS request failed: ${error.message}\n`);
  }
}

// Test Anthropic API key
async function testAnthropicAPIKey() {
  console.log('3. Testing ANTHROPIC_API_KEY...');

  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('   ❌ ANTHROPIC_API_KEY not found in environment\n');
    return;
  }

  console.log(`   API Key prefix: ${process.env.ANTHROPIC_API_KEY.substring(0, 12)}...`);

  // Send a basic request to Anthropic API
  const options = {
    hostname: 'api.anthropic.com',
    port: 443,
    path: '/v1/complete',
    method: 'POST',
    headers: {
      'x-api-key': process.env.ANTHROPIC_API_KEY,
      'content-type': 'application/json',
      'anthropic-version': '2023-06-01'
    }
  };

  const postData = JSON.stringify({
    prompt: '\n\nHuman: Hello\n\nAssistant:',
    model: 'claude-2.1', // Using a model that requires a valid key
    max_tokens_to_sample: 10
  });

  try {
    const result = await makeHttpsRequest(options, postData);
    const jsonResult = JSON.parse(result);

    // A valid key will either succeed or return specific error messages
    if (jsonResult.error && (jsonResult.error.type === 'authentication_error' || jsonResult.error.type === 'invalid_request_error')) {
      console.log('   ✅ Anthropic API key format appears valid (received expected API error)\n');
    } else if (jsonResult.completion !== undefined) {
      console.log('   ✅ Anthropic API key is active and working\n');
    } else {
      console.log('   ❓ Unexpected Anthropic API response\n');
    }
  } catch (error) {
    console.log(`   ❌ Anthropic API request failed: ${error.message}\n`);
  }
}

// Test Stripe API key
async function testStripeAPIKey() {
  console.log('4. Testing STRIPE_SECRET_KEY...');

  if (!process.env.STRIPE_SECRET_KEY) {
    console.log('   ❌ STRIPE_SECRET_KEY not found in environment\n');
    return;
  }

  console.log(`   API Key prefix: ${process.env.STRIPE_SECRET_KEY.substring(0, 12)}...`);

  // Send a basic request to Stripe API
  const options = {
    hostname: 'api.stripe.com',
    port: 443,
    path: '/v1/charges',
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}`,
      'Content-Type': 'application/x-www-form-urlencoded'
    }
  };

  try {
    const result = await makeHttpsRequest(options, '');
    const jsonResult = JSON.parse(result);

    // A valid key will return either charges data or a specific error
    if (jsonResult.error && jsonResult.error.code === 'authentication_required') {
      console.log('   ✅ Stripe API key format appears valid (received expected API error)\n');
    } else if (jsonResult.data !== undefined) {
      console.log('   ✅ Stripe API key is active and working\n');
    } else {
      console.log('   ❓ Unexpected Stripe API response\n');
    }
  } catch (error) {
    console.log(`   ❌ Stripe API request failed: ${error.message}\n`);
  }
}

// Test Logfire token
async function testLogfireToken() {
  console.log('5. Testing LOGFIRE_TOKEN...');

  if (!process.env.LOGFIRE_TOKEN) {
    console.log('   ❌ LOGFIRE_TOKEN not found in environment\n');
    return;
  }

  console.log(`   Token prefix: ${process.env.LOGFIRE_TOKEN.substring(0, 12)}...`);

  // Send a basic request to Logfire API (if exists)
  const options = {
    hostname: 'logfire.sh',
    port: 443,
    path: '/api/v1/projects',
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${process.env.LOGFIRE_TOKEN}`,
      'Content-Type': 'application/json'
      'Accept': 'application/json'
    }
  };

