// Simple application for agent to work on
// Enhanced with better error handling, input validation, and security practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet());

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Input validation helper function
const validateId = (id) => {
  const numId = parseInt(id, 10);
  if (isNaN(numId) || numId <= 0) {
    const error = new Error('Invalid ID provided');
    error.statusCode = 400;
    throw error;
  }
  return numId;
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    // Log error internally but don't expose details to client
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get all users endpoint
app.get('/users', (req, res) => {
  try {
    // In a real application, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize output - remove sensitive data if needed
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name
      // Note: Not exposing emails in this example for privacy
    }));

    res.json(sanitizedUsers);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

// Get user by ID endpoint with input validation
app.get('/users/:id', (req, res) => {
  try {
    // Validate input
    const userId = validateId(req.params.id);

    // Sample user data (would normally come from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Sanitize output
    const { email, ...sanitizedUser } = user;
    res.json(sanitizedUser);
  } catch (error) {
    if (error.statusCode) {
      return res.status(error.statusCode).json({ error: error.message });
    }
    console.error('Error fetching user:', error);
    res.status(500).json({ error: 'Failed to retrieve user' });
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use proper logging solution)
  console.error('Unhandled error:', err);

  // Check if headers have already been sent
  if (res.headersSent) {
    return next(err);
  }

  // Respond with appropriate error message
  if (err.statusCode) {
    res.status(err.statusCode).json({ error: err.message });
  } else {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Handle 404 routes
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Process terminated');
    process.exit(0);
  });
});

module.exports = app;

