// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const validator = require('validator');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Input validation helper function
const validateId = (id) => {
  return validator.isInt(id, { min: 1 });
};

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ 
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? 'Something went wrong!' : err.message 
  });
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters if any are provided
    const { limit, offset } = req.query;

    if (limit && !validator.isInt(limit, { min: 1, max: 100 })) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter. Must be an integer between 1 and 100.' 
      });
    }

    if (offset && !validator.isInt(offset, { min: 0 })) {
      return res.status(400).json({ 
        error: 'Invalid offset parameter. Must be a positive integer.' 
      });
    }

    // In a real app, these would come from a database with proper pagination
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (error) {
    next(error);
  }
});

// Get specific user by ID with validation
app.get('/users/:id', (req, res, next) => {
  try {
    const userId = req.params.id;

    // Validate user ID
    if (!validateId(userId)) {
      return res.status(400).json({ 
        error: 'Invalid user ID. Must be a positive integer.' 
      });
    }

    // In a real app, this would query a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === parseInt(userId));

    if (!user) {
      return res.status(404).json({ 
        error: 'User not found' 
      });
    }

    res.json(user);
  } catch (error) {
    next(error);
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Endpoint not found' 
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

