#!/usr/bin/env node

// Test script to verify if the credentials in .env.test are still valid
// This is for security auditing purposes only

require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const fetch = require('node-fetch');

async function testDatabaseConnection() {
  console.log('Testing DATABASE_URL...');

  if (!process.env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found in environment');
    return false;
  }

  const client = new Client({
    connectionString: process.env.DATABASE_URL,
  });

  try {
    await client.connect();
    console.log('✅ Database connection successful');
    await client.end();
    return true;
  } catch (error) {
    console.log(`❌ Database connection failed: ${error.message}`);
    return false;
  }
}

async function testAWSKeys() {
  console.log('\nTesting AWS credentials...');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found in environment');
    return false;
  }

  try {
    // Simple test using STS GetCallerIdentity (doesn't cost anything)
    const response = await fetch('https://sts.amazonaws.com/', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Authorization': `AWS4-HMAC-SHA256 Credential=${process.env.AWS_ACCESS_KEY_ID}/20230101/us-east-1/sts/aws4_request, SignedHeaders=host;x-amz-date, Signature=generated_signature`
      },
      body: 'Action=GetCallerIdentity&Version=2011-06-15'
    });

    // If we get a 403 with SignatureDoesNotMatch, the key exists but signature is wrong
    // If we get a 401 with AuthFailure, the key is invalid
    // If we get a successful response, the key works
    if (response.status === 403) {
      console.log('✅ AWS credentials appear to be valid (signature error expected without proper signing)');
      return true;
    } else if (response.status === 401) {
      console.log('❌ AWS credentials appear to be invalid');
      return false;
    } else {
      console.log(`❓ Unexpected response from AWS: ${response.status}`);
      return false;
    }
  } catch (error) {
    console.log(`❌ Failed to test AWS credentials: ${error.message}`);
    return false;
  }
}

async function testAnthropicAPIKey() {
  console.log('\nTesting ANTHROPIC_API_KEY...');

  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found in environment');
    return false;
  }

  try {
    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': process.env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01'
      },
      body: JSON.stringify({
        model: 'claude-3-haiku-20240307',
        messages: [{ role: 'user', content: 'Hello' }],
        max_tokens: 10
      })
    });

    // A 400 Bad Request means the key is valid but the request was malformed
    // A 401 Unauthorized means the key is invalid
    if (response.status === 401) {
      console.log('❌ ANTHROPIC_API_KEY appears to be invalid');
      return false;
    } else if (response.status >= 400) {
      console.log('✅ ANTHROPIC_API_KEY appears to be valid (request was processed)');
      return true;
    } else {
      console.log('✅ ANTHROPIC_API_KEY is valid');
      return true;
    }
  } catch (error) {
    console.log(`❌ Failed to test ANTHROPIC_API_KEY: ${error.message}`);
    return false;
  }
}

async function testStripeKey() {
  console.log('\nTesting STRIPE_SECRET_KEY...');

  if (!process.env.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not found in environment');
    return false;
  }

  try {
    const response = await fetch('https://api.stripe.com/v1/charges', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}`,
      }
    });

    // A 401 means invalid key
    // Any other response means the key is valid (even if it's a 400 for bad request)
    if (response.status === 401) {
      console.log('❌ STRIPE_SECRET_KEY appears to be invalid');
      return false;
    } else {
      console.log('✅ STRIPE_SECRET_KEY appears to be valid');
      return true;
    }
  } catch (error) {
    console.log(`❌ Failed to test STRIPE_SECRET_KEY: ${error.message}`);
    return false;
  }
}

async function main() {
  console.log('Credential Validation Script');
  console.log('===========================');

  // Load environment variables from .env.test
  const fs = require('fs');
  if (!fs.existsSync('.env.test')) {
    console.log('❌ .env.test file not found');
    process.exit(1);
  }

  console.log('Found .env.test file, loading environment variables...\n');

  try {
    let results = [];

    results.push(await testDatabaseConnection());
    results.push(await testAWSKeys());
    results.push(await testAnthropicAPIKey());
    results.push(await testStripeKey());

    console.log('\nSummary:');
    console.log('========');
    console.log(`${results.filter(r => r).length} out of ${results.length} credentials appear to be valid`);

    if (results.some(r => r === null)) {
      console.log('Some tests could not be completed due to missing dependencies');
    }

  } catch (error) {
    console.error('Error during credential testing:', error);
    process.exit(1);
  }
}

if (require.main === module) {
  main();
}

