#!/usr/bin/env node

// Test script to verify if the credentials in .env.test are still valid
// This is for security auditing purposes only

const fs = require('fs');
const https = require('https');

// Parse .env.test file manually
function loadEnvFile() {
  const env = {};
  try {
    const content = fs.readFileSync('.env.test', 'utf8');
    const lines = content.split('\n');
    for (const line of lines) {
      if (line.trim() === '' || line.startsWith('#')) continue;
      const [key, value] = line.split('=');
      if (key && value) {
        env[key.trim()] = value.trim();
      }
    }
  } catch (error) {
    console.error('Failed to read .env.test:', error.message);
  }
  return env;
}

const envVars = loadEnvFile();

// Helper function for making HTTPS requests
function httpsRequest(options, postData) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve({ statusCode: res.statusCode, headers: res.headers, data }));
    });
    req.on('error', reject);
    if (postData) {
      req.write(postData);
    }
    req.end();
  });
}

