// Secure Express application with improved error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const validator = require('validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(cors());   // Enable CORS with options as needed

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use(limiter);

// Middleware to parse JSON bodies
app.use(express.json());

// Health endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    // Log the error internally but don't expose details to client
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if present
    const { limit, page } = req.query;

    // Basic input validation
    let validatedLimit = 10; // default
    let validatedPage = 1;   // default

    if (limit) {
      if (!validator.isInt(limit, { min: 1, max: 100 })) {
        return res.status(400).json({ 
          error: 'Invalid limit parameter. Must be an integer between 1 and 100.' 
        });
      }
      validatedLimit = parseInt(limit, 10);
    }

    if (page) {
      if (!validator.isInt(page, { min: 1 })) {
        return res.status(400).json({ 
          error: 'Invalid page parameter. Must be a positive integer.' 
        });
      }
      validatedPage = parseInt(page, 10);
    }

    // In a real app, this would come from a database with proper pagination
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simulate pagination
    const startIndex = (validatedPage - 1) * validatedLimit;
    const paginatedUsers = users.slice(startIndex, startIndex + validatedLimit);

    res.json({
      users: paginatedUsers,
      pagination: {
        page: validatedPage,
        limit: validatedLimit,
        total: users.length
      }
    });
  } catch (error) {
    // Log the error internally but don't expose details to client
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Generic error handling middleware
app.use((err, req, res, next) => {
  // Log error for internal tracking
  console.error('Unhandled error:', err);

  // Send generic error response to client
  res.status(500).json({ 
    error: 'An unexpected error occurred' 
  });
});

// Handle 404s for undefined routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Route not found' 
  });
});

// Start server only if this file is run directly
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

