  },
}));

// Request logging and monitoring
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Health endpoint with proper error handling
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with improved structure
app.get('/users', (req, res) => {
  try {
    // In a real application, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simulate potential query parameters that should be validated
    const { limit } = req.query;

    // Basic validation of query parameters
    if (limit && (isNaN(limit) || parseInt(limit) < 0)) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter' 
      });
    }

    const result = limit ? users.slice(0, parseInt(limit)) : users;
    res.status(200).json(result);
  } catch (error) {
    console.error('Error fetching users:', error);
    // Don't expose internal errors to clients
    res.status(500).json({ 
      error: 'Failed to fetch users' 
    });
  }
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Check if headers have already been sent
  if (res.headersSent) {
    return next(err);
  }

  // Send generic error message to client
  res.status(500).json({ 
    error: 'Internal server error' 
  });
});

// Handle 404 routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Route not found' 
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

