// Simple application for agent to work on
// Enhanced with better error handling, input validation, and security practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const validator = require('validator');

const app = express();

// Security headers
app.use(helmet());

// Enable CORS with options
app.use(cors());

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Middleware for request logging
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Simulated user data (in a real app, this would come from a database)
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ 
    error: 'Something went wrong!',
    timestamp: new Date().toISOString()
  });
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Get users with input validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters if present
    const { limit, page } = req.query;

    let usersToSend = [...users];

    // Validate limit parameter
    if (limit !== undefined) {
      const limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum <= 0 || limitNum > 100) {
        return res.status(400).json({ 
          error: 'Invalid limit parameter. Must be a number between 1 and 100.' 
        });
      }
      usersToSend = usersToSend.slice(0, limitNum);
    }

    // Validate page parameter
    if (page !== undefined) {
      const pageNum = parseInt(page, 10);
      if (isNaN(pageNum) || pageNum <= 0) {
        return res.status(400).json({ 
          error: 'Invalid page parameter. Must be a positive integer.' 
        });
      }
      // Simple pagination logic
      const pageSize = limit ? parseInt(limit, 10) : 10;
      const startIndex = (pageNum - 1) * pageSize;
      usersToSend = users.slice(startIndex, startIndex + pageSize);
    }

    res.json({
      users: usersToSend,
      total: users.length,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error);
  }
});

// Get specific user by ID with validation
app.get('/users/:id', (req, res, next) => {
  try {
    // Validate user ID
    const userId = req.params.id;

    if (!validator.isNumeric(userId)) {
      return res.status(400).json({ 
        error: 'Invalid user ID. Must be a numeric value.' 
      });
    }

    const id = parseInt(userId, 10);
    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({ 
        error: 'User not found' 
      });
    }

    res.json({
      user,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error);
  }
});

// Global 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Route not found',
    timestamp: new Date().toISOString()
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

