#!/usr/bin/env node

// Script to verify the credentials in .env.test
require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const https = require('https');

async function testDatabaseConnection() {
  console.log('Testing DATABASE_URL...');

  if (!process.env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found in environment');
    return false;
  }

  try {
    const client = new Client({
      connectionString: process.env.DATABASE_URL,
      ssl: {
        rejectUnauthorized: false // For testing purposes only
      }
    });

    await client.connect();
    console.log('✅ DATABASE_URL connection successful');
    await client.end();
    return true;
  } catch (error) {
    console.log(`❌ DATABASE_URL connection failed: ${error.message}`);
    return false;
  }
}

function testAWSKeys() {
  console.log('\nChecking AWS credentials...');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found in environment');
    return false;
  }

  // Basic format check - AWS Access Key IDs should start with AKIA
  if (!process.env.AWS_ACCESS_KEY_ID.startsWith('AKIA')) {
    console.log('❌ Invalid AWS Access Key ID format');
    return false;
  }

  // Check length - Access Key IDs are typically 20 characters
  if (process.env.AWS_ACCESS_KEY_ID.length !== 20) {
    console.log('❌ Invalid AWS Access Key ID length');
    return false;
  }

  console.log('✅ AWS credentials present with correct format');
  return true;
}

function testAnthropicKey() {
  console.log('\nChecking Anthropic API key...');

  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found in environment');
    return false;
  }

  // Basic format check - Anthropic keys start with 'sk-ant-'
  if (!process.env.ANTHROPIC_API_KEY.startsWith('sk-ant-')) {
    console.log('❌ Invalid Anthropic API key format');
    return false;
  }

  console.log('✅ Anthropic API key present with correct format');
  return true;
}

function testStripeKey() {
  console.log('\nChecking Stripe secret key...');

  if (!process.env.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not found in environment');
    return false;
  }

  // Basic format check - Live Stripe keys start with 'sk-live-'
  if (!process.env.STRIPE_SECRET_KEY.startsWith('sk-live-')) {
    console.log('❌ Invalid Stripe secret key format');
    return false;
  }

  console.log('✅ Stripe secret key present with correct format');
  return true;
}

// Run all tests
async function runAllTests() {
  console.log('Starting credential verification...\n');

  const results = [];

  // Load additional dependencies dynamically if available
  try {
    results.push(await testDatabaseConnection());
  } catch (error) {
    console.log('⚠️  Database test skipped (pg module not available)');
    results.push(false);
  }

  results.push(testAWSKeys());
  results.push(testAnthropicKey());
  results.push(testStripeKey());

  console.log('\n--- Summary ---');
  const passed = results.filter(r => r).length;
  const total = results.length;
  console.log(`Passed: ${passed}/${total} tests`);

  if (passed === total) {
    console.log('✅ All credentials appear valid');
  } else {
    console.log('❌ Some credentials may be invalid or inaccessible');
  }
}

runAllTests();

