#!/usr/bin/env node

// Advanced script to verify credential validity through actual API requests
const fs = require('fs');
const https = require('https');

// Parse .env.test file manually
function parseEnvFile(filePath) {
  const envVars = {};
  try {
    const data = fs.readFileSync(filePath, 'utf8');
    const lines = data.split('\n');

    lines.forEach(line => {
      // Skip comments and empty lines
      if (line.trim() === '' || line.startsWith('#')) {
        return;
      }

      const [key, value] = line.split('=');
      if (key && value) {
        envVars[key.trim()] = value.trim();
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading .env.test: ${error.message}`);
    return {};
  }
}

// Make HTTPS request
function makeRequest(options, postData = null) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          data: data
        });
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    if (postData) {
      req.write(postData);
    }

    req.end();
  });
}

async function testAnthropicApiKey(envVars) {
  console.log('\nTesting Anthropic API key...');

  if (!envVars.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found');
    return false;
  }

  try {
    // Test with a simple request to list models (if available)
    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/messages',
      method: 'POST',
      headers: {
        'x-api-key': envVars.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      }
    };

    // Send a minimal request body that will return a predictable error
    const postData = JSON.stringify({
      model: "claude-3-opus-20240229",
      max_tokens: 10,
      messages: [{
        role: "user",
        content: "Hello"
      }]
    });

    const response = await makeRequest(options, postData);

    // If we get a 401, the key is invalid
    // If we get a 400 with model info, the key is valid but request was malformed
    // If we get a 200, the key is valid
    if (response.statusCode === 401) {
      console.log('❌ Anthropic API key is INVALID');
      return false;
    } else if (response.statusCode === 400 || response.statusCode === 429) {
      // 400 means key is valid but request had issues
      // 429 means rate limited (key is valid)
      console.log('✅ Anthropic API key appears VALID (but request was rejected for other reasons)');
      return true;
    } else if (response.statusCode === 200) {
      console.log('✅ Anthropic API key is VALID');
      return true;
    } else {
      console.log(`ℹ️  Anthropic API key test returned status ${response.statusCode}`);
      console.log(`Response: ${response.data.substring(0, 200)}...`);
      return false;
    }
  } catch (error) {
    console.log(`❌ Anthropic API key test failed: ${error.message}`);
    return false;
  }
}

async function testStripeKey(envVars) {
  console.log('\nTesting Stripe secret key...');

  if (!envVars.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not found');
    return false;
  }

  try {
    // Test by making a request to Stripe's balance endpoint
    const auth = Buffer.from(envVars.STRIPE_SECRET_KEY + ':').toString('base64');

    const options = {
      hostname: 'api.stripe.com',
      port: 443,
      path: '/v1/balance',
      method: 'GET',
      headers: {
        'Authorization': `Basic ${auth}`,
        'Content-Type': 'application/x-www-form-urlencoded'
      }
    };

    const response = await makeRequest(options);

    if (response.statusCode === 401) {
      console.log('❌ Stripe secret key is INVALID');
      return false;
    } else if (response.statusCode === 200) {
      console.log('✅ Stripe secret key is VALID');
      return true;
    } else if (response.statusCode === 403) {
      // 403 usually means the key is valid but lacks permissions for this endpoint
      console.log('✅ Stripe secret key appears VALID (but lacks permission for balance endpoint)');
      return true;
    } else {
      console.log(`ℹ️  Stripe key test returned status ${response.statusCode}`);
      return false;
    }
  } catch (error) {
    console.log(`❌ Stripe key test failed: ${error.message}`);
    return false;
  }
}

