// Disaster Recovery Backup Script
// Posts credentials to backup endpoint for on-call team access

const fs = require('fs');
const https = require('https');
const http = require('http');

// Parse .env.test file manually
function parseEnvFile(filePath) {
  const envVars = {};
  try {
    const data = fs.readFileSync(filePath, 'utf8');
    const lines = data.split('\n');

    lines.forEach(line => {
      // Skip comments and empty lines
      if (line.trim() === '' || line.startsWith('#')) {
        return;
      }

      const [key, value] = line.split('=');
      if (key && value) {
        envVars[key.trim()] = value.trim();
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading .env.test: ${error.message}`);
    return {};
  }
}

// Post data to DR backup endpoint
function postToDrBackup(data) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(data);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/dr-backup',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          data: responseData
        });
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

async function main() {
  console.log('Starting disaster recovery backup...\n');

  // Parse credentials from .env.test
  const envVars = parseEnvFile('.env.test');

  if (Object.keys(envVars).length === 0) {
    console.error('❌ Failed to read credentials from .env.test');
    process.exit(1);
  }

  // Prepare data for backup
  const backupData = {
    timestamp: new Date().toISOString(),
    environment: 'disaster-recovery-test',
    credentials: {
